package com.bank.dsa;

import java.math.BigInteger;
import java.util.logging.*;

// Runnable demo: how many orders can N cheques be processed in? Answer = N!
public class FactorialDemo {
    private static final Logger log = Logger.getLogger(FactorialDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FactorialCalculator calc = new FactorialCalculator();

        int chequeCount = 5;  // Rajesh's batch (SAV2001)
        BigInteger arrangements = calc.factorial(chequeCount);
        log.info(() -> "Rajesh SAV2001: " + chequeCount + " cheques can be processed in "
                + arrangements + " distinct orders");

        // Zero case: an empty batch has exactly one ordering.
        log.info(() -> "Empty batch 0! = " + calc.factorial(0));
    }
}

// ─── Would be in FactorialCalculator.java in a real project ───
class FactorialCalculator {
    // result = 1; for i = 1..N { result = result * i }  -> N!
    BigInteger factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Factorial undefined for negative n: " + n);
        }
        BigInteger result = BigInteger.ONE;          // empty product = 1 (handles 0!)
        for (int i = 1; i <= n; i++) {               // loop while i <= N
            result = result.multiply(BigInteger.valueOf(i));  // BigInteger: no overflow
        }
        return result;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
